def f_avg_no_overflow(a, b):
    return a + ((b - a) >> 1)

def f_lerp_half(a, b):
    return a + ((b - a) >> 1)

def f_diff_or_zero(a, b):
    return (a - b) & -(a > b)

def f_popcount8(a):
    x = a & 255
    x = x - ((x >> 1) & 85)
    x = (x & 51) + ((x >> 2) & 51)
    return (x + (x >> 4)) & 15

def f_parity8(a):
    x = a & 255
    x = x ^ (x >> 4)
    x = x ^ (x >> 2)
    return (x ^ (x >> 1)) & 1

def f_hamming8(a, b):
    x = (a ^ b) & 255
    x = x - ((x >> 1) & 85)
    x = (x & 51) + ((x >> 2) & 51)
    return (x + (x >> 4)) & 15

def f_trailing_zeros8(a):
    x = a & 255
    t = x & -x
    return ((t & 170) != 0) + (((t & 204) != 0) << 1) + (((t & 240) != 0) << 2) + ((x == 0) << 3)

